/* @lc app=leetcode id=2328 lang=kotlin */ class Solution { fun countPaths(grid: Array<IntArray>): Int = Array(grid.size) { IntArray(grid[0].size) { -1 } }.let { dp -> DeepRecursiveFunction<Pair<Int, Int>, Int> { (r, c) -> if (dp[r][c] != -1) dp[r][c] else (1 + listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0).sumOf { (dr, dc) -> (r + dr).let { nr -> (c + dc).let { nc -> if (nr in grid.indices && nc in grid[0].indices && grid[nr][nc] > grid[r][c]) callRecursive(nr to nc).toLong() else 0L } } }).let { (it % 1000000007).toInt() }.also { dp[r][c] = it } }.let { dfs -> grid.indices.sumOf { r -> grid[0].indices.sumOf { c -> dfs(r to c).toLong() } % 1000000007 } % 1000000007 }.toInt() } }